def prime_length(string):
    def is_prime(n):
        """Check if a number or string is prime or not"""
        if type(n) not in [int, str]:
            try:
                if int(n) == 1:
                    return False
            except:
                return False
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    if type(string) not in [int, str]:
        string = str(string)

    count = 0
    for char in string:
        if char == ' ':
            continue
        if char.isalpha():
            count = 0
        else:
            count += 1
            if count == 2:
                continue

    if count == len(string) / 2:
        return True
    return False

