def split_words(txt):
    # Split the string on whitespace, if there is no whitespace, return a list of words without any whitespace
    words = txt.split()
    # Split the string on comma if it doesn't contain commas
    if ',' not in words:
        return words
    # Split the string on commas if it does contain commas
    else:
        return words.replace(',', '').split(',')

