def split_words(txt):
    # Check for spaces in the text
    if ' ' in txt or '\n' in txt:
        return txt.split()
    # Check for commas in the text
    elif ',' in txt:
        return txt.split(',')
    else:
        # Return the number of lower-case letters with odd order in the alphabet
        return len([char for char in txt if char.islower() and ord(char) % 2 != 0])

# Test cases
assert split_words("Hello world!") == ["Hello", "world!"]
assert split_words("Hello,world!") == ["Hello", "world!"]
assert split_words("abcdef") == 3
```

