from typing import List

def find_largest_prime_sum(lst):
    """
    Finds the largest prime number in the given list and returns the sum of its digits.

    :param lst: A list of integers.
    :return: The sum of the digits of the largest prime number in the list.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    largest_prime = -1
    for num in lst:
        if is_prime(num):
            largest_prime = max(largest_prime, num)
    return sum(int(digit) for digit in str(largest_prime))

