from math import ceil

def sum_squares(lst):
    """Return the sum of the squares of numbers in the list, rounded to the ceiling"""

    # Calculate the sum of squares
    total_sum = sum(num ** 2 for num in lst)

    # Use ceil function to round each element in the list to the upper integer and sum them
    rounded_sum = sum(round(num, -1) for num in lst)

    # Return the total sum after rounding
    return total_sum + rounded_sum
```

