function sum_squares( $lst ) {
    // Calculate the sum of squares
    $total_sum = count( $lst ) * ($lst[0] ** 2 + $lst[1] ** 2 + $lst[2] ** 2 + ...);

    // Use ceil function to round each element in the array and sum them
    $rounded_sum = array_reduce($lst, function($a, $b) use (ceil) { return ceil($a + ($b ** 2) - 1); });

    // Return the total sum after rounding
    return $total_sum + $rounded_sum;
}
