from typing import List

def search(lst: List[int]) -> int:
    """
    Your task is to find the greatest integer that is greater than zero and has a frequency greater than or equal to the integer itself.
    The frequency of an integer is the number of times it appears in the list.
    If no such a value exist, return -1.
    """
    frequency_dict = {}
    for num in lst:
        if num == 0:
            return -1
        frequency_dict[num] = frequency_dict.get(num, 0) + 1
    greatest_value = -1
    for num in frequency_dict:
        if frequency_dict[num] >= num and num >= greatest_value:
            greatest_value = num
    return greatest_value
