        while i < j:
            if arr[i] != arr[j]:
                return False
            i += 1
            j -= 1
        return True

    def find_min_changes(arr, changes):
        min_changes = changes
        N = len(arr)
        for i in range(N):
            j = i + min_changes
            while j < N and is_palindrome(arr[j]):
                j += 1
            min_changes += 1
        return min_changes

    return find_min_changes(arr, 0)
