import sys

def bf(planet1, planet2):
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()
    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]
    planets.sort()
    result = []
    for i in range(len(planets) - 1):
        if planets[i] < planet1 < planets[i + 1]:
            result.append(planets[i])
    return tuple(result)

# Example usage
print(bf("Jupiter", "Neptune"))  # Output: ("Saturn", "Uranus")
print(bf("Earth", "Mercury"))    # Output: ("Venus")
print(bf("Mercury", "Uranus"))   # Output: ("Venus", "Earth", "Mars", "Jupiter", "Saturn")
