from typing import List

def is_sum_of_digits_binary_sum(num: int) -> bool:
    """Check if the sum of the digits of a number in binary is equal to the number itself."""
    return bin(num).count('1') == num

def solve(N: int) -> str:
    """Given a positive integer N, return the total sum of its digits in binary."""
    digits = [int(d) for d in str(N)]
    return bin(N).count('1') == digits[0]

def sum_of_digits_binary(N: int) -> str:
    """Return the sum of digits in binary of a number."""
    if is_sum_of_digits_binary_sum(N):
        return "1"
    return solve(N)

