def is_nested(sub_sequence):
    stack = []
    for char in sub_sequence:
        if char in ['(','{']:
            stack.append(char)
        elif char in [')','}']:
            if len(stack) == 0 or stack.pop() != char:
                return False
    return len(stack) == 0  # If stack is empty at the end of the loop, return True
