def is_nested(string):
    def nested_bracks(open, close):
        return open != close

    stack = []

    for char in string.strip():
        if char in '([{':
            stack.append(char)
        else:
            if not stack:
                return False
            open_bracket, close_bracket = stack.pop(), char
            if nested_bracks(open_bracket, close_bracket):
                stack.append(close_bracket)

    return not stack

