def solution(lst):
    """Given a non-empty list of integers, return the sum of all of the odd elements that are in even positions.
"""

    def get_even_positions(lst):
        return [i for i, x in enumerate(lst) if i % 2 == 0]

    def is_odd(x):
        return x % 2 != 0

    def get_odd_element(x):
        return x if is_odd(x) else None

    def sum_of_evens(lst):
        even_elements = lst[::2]  # Select even positions
        return sum(get_odd_element(x) for x in even_elements) if even_elements else 0

    return sum_of_evens(lst)
