import sys

def monotonic(l: list):
    """Return True if the elements of the list are monotonically increasing or decreasing."""
    if not l:
        return True
    else:
        wasIncreasing = l[1] > l[0]
        for i in range(2, len(l)):
            if not wasIncreasing:
                return False
            wasIncreasing = l[i] > l[i-1]
        return True

