def is_sorted(lst):
    # Check if the list is empty or has one element
    if not lst or len(lst) <= 1:
        return True

    # Check if any element is greater than the next element
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    return True
```

