def iscube(a):
    # Check if the input is an integer
    if not isinstance(a, int):
        return False
    # Check if the input is non-negative
    if a < 0:
        return False
    # Check if the input is a perfect cube
    cubed = a ** (1/3)
    if cubed == int(cubed):
        return True
    else:
        return False
