def sum_squares(lst):
    sum = 0
    for i, value in enumerate(lst):
        if i % 3 == 0 and value % 3 == 0:
            sum += value ** 2
        elif i % 4 == 0 and value % 4 == 0:
            sum += value ** 3
        else:
            sum += value
    return sum

# Example usage:
print(sum_squares([1, 2, 3]))  # Output: 6
print(sum_squares([]))  # Output: 0
print(sum_squares([-1, -5, 2, -1, -5]))  # Output: -126

