def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False
    # Extract month, day, and year from the date string
    month, day, year = date.split('-')
    # Check if the month is between 1 and 12 (inclusive)
    if not (1 <= int(month) <= 12):
        return False
    # Check if the day is between 1 and 31 (inclusive)
    if not (1 <= int(day) <= 31):
        return False
    # Check if the year is between 1 and 12 (inclusive)
    if not (1 <= int(year) <= 12):
        return False
    # Check if the year is a leap year
    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    # Check if the year is a common year
    else:
        return True
```

