    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Split the input string into a list of characters
    chars = list(test)

    # Create a dictionary to count the occurrences of each character
    char_count = {}
    for char in chars:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the character with the maximum occurrence
    max_char = max(char_count, key=char_count.get)

    # Return the character and its count
    return {'char': max_char, 'count': char_count[max_char]}

