    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Count the frequency of each letter
    letter_count = {}
    for letter in test:
        if letter in letter_count:
            letter_count[letter] += 1
        else:
            letter_count[letter] = 1

    # Find the letter with the maximum frequency
    max_frequency = max(letter_count.values())
    # Filter the letters that have the maximum frequency
    result = {letter: frequency for letter, frequency in letter_count.items() if frequency == max_frequency}

    return result
