def correct_bracketing(brackets: str):
    # Initialize a counter for tracking unmatched opening brackets
    unmatched_bracket_count = 0

    # Iterate through each character in the string
    for char in brackets:
        # If an opening bracket is found, increment the counter
        if char == "<":
            unmatched_bracket_count += 1
        # If a closing bracket is found, decrement the counter
        elif char == ">":
            if unmatched_bracket_count > 0:
                unmatched_bracket_count -= 1
            else:
                return False
    # If the counter becomes zero, all brackets are properly matched
    return unmatched_bracket_count == 0
```

