def find_largest_prime_sum(nums):
    """
    Finds the largest prime value in the list and returns the sum of its digits.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    largest_prime = float('-inf')
    sum_of_digits = 0
    for num in nums:
        if is_prime(num):
            sum_of_digits += num
            if is_prime(sum_of_digits):
                largest_prime = max(largest_prime, sum_of_digits)
    return largest_prime + sum_of_digits

