def is_equal_to_sum_even(n):
    # Check if n is even
    if n % 2 != 0:
        return False

    # Check all sets of 4 positive even numbers that sum to n
    for i in range(1, n // 2 + 1):
        for j in range(i + 1, n // 2 + 1):
            for k in range(j + 1, n // 2 + 1):
                l = n - (i + j + k)
                if l > 0 and l % 2 == 0:
                    return True
    return False
```

