def modp(n: int, p: int):
    product = 1
    x = n

    if p == 2:
        while x:
            if x & 1:
                product *= n
            n = n ** 2
            x >>= 1
            n = n // p

    else:
        # Handle numerical errors due to use of inequality operation
        while p % 2 == 1:
            p -= 2

        while p > 1:
            if (p & 1) == 1:
                product *= (n ** (p // 2))  # Each co-efficient for a multiple of p
            n *= n
            p = p // 2

        if p > 0 and n != 1:
            product *= (2 ** p)

    return product % p

```

