def select_words(s, n):
    # Helper function to find consonants in a word
    def has_consonants(s):
        consonants = "bcdfghjklmnpqrstvwxyz"
        return any(char in consonants for char in s.lower())

    # Filter words containing exactly n consonants
    return [' '.join([word, str(len(w))]) for word in s.split() if has_consonants(word) == n]
