def count_nums(arr):
    count = 0
    for num in arr:
        if num < 0:
            num = -num
            count += 1
        temp = 0
        while num > 0:
            temp = temp * 10 + num % 10
            num //= 10
        if temp > 0:
            count += 1
    return count
