def check_dict_case(dict):
    if dict == {}:  # Check if the dictionary is empty
        return True

    case_types = set()
    for key in set(dict.keys()):
        type_ = type(key)
        if type_ in case_types:
            continue
        case_types.add(type_)

    all_lower = False
    if all(isinstance(key.lower(), str) for key in case_types):
        all_lower = True
    else:
        all_lower = False

    all_upper = False
    if all(isinstance(key.upper(), str) for key in case_types):
        all_upper = True
    else:
        all_upper = False

    return all_lower and all_upper  # Return True if dictionary keys have all lowercase or uppercase and all have the correct type, else return False
