def encode(message):
    result = ''
    for char in message:
        if char.isalpha():
            # Check if the character is a vowel
            if char.lower() in 'aeiou':
                # Replace the vowel with the character 2 places ahead in the alphabet
                result += chr((ord(char.lower()) - ord('a') - 2) % 26 + ord('a'))
            else:
                # Convert the character to uppercase
                result += char.upper()
        else:
            # If the character is not a letter, leave it as is
            result += char
    return result

