def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None

    longest_str = strings[0]
    longest_len = len(longest_str)

    for str_ in strings:
        if len(str_) > longest_len:
            longest_str = str_
            longest_len = len(longest_str)

