def intersection(interval1, interval2):
    """Determine if the length of the intersection of two intervals is a prime number."""
    # Calculate the intersection interval
    intersection_interval = (max(interval1[0], interval2[0]), min(interval1[1], interval2[1]))
    # Check if the length of the intersection is a prime number
    if intersection_interval[0] == 0:
        return "YES"
    for num in range(2, int(intersection_interval[1] + 1)):
        if intersection_interval[0] % num == 0:
            return "NO"
    return "YES"
