import math

def closest_integer(value):
    # Normalize the value
    normalize_value = float(value)

    # Check if the normalized value is close to zero
    if math.isclose(normalize_value, 0):
        # Determine the closest integer based on the absolute value of the original value
        if abs(normalize_value) < 0.5:
            return math.floor(normalize_value)
        else:
            # If the absolute value is not close to zero, round away from zero
            return math.ceil(normalize_value)
    else:
        # If the normalized value is not close to zero, take the ceiling or floor
        # based on where 'value' is relative to 0 in the domain (-10000, 10000)
        if normalize_value <= -10000:
            return -10000
        elif normalize_value >= 10000:
            return 10000
        elif normalize_value < 0.5:
            return int(normalize_value + 1)
        else:
            return int(normalize_value - 1)
