import math

def closest_integer(value):
    result = 0
    if value == '':
        return result
    elif value.startswith('-'):
        value = value[1:]  # Remove negative sign before converting to int
    elif value.endswith('-'):
        value = value[:-1] # Remove positive sign after converting to int
    else:
        value = int(value)  # Convert to int before finding closest

    if value == int(value):  # Check if the value is already closest integer
        return value
    elif value > result:
        result = value
        if int(value) != (result - 0.5):
            return result
    elif value < result:
        result = int(value)
        if int(value) != (result + 0.5):
            return int(value)
    else:
        result = int(value) - 0.5

    return result
