def total_match(lst1, lst2):
    if len(lst1) > len(lst2):
        return lst1
    elif len(lst1) < len(lst2):
        return lst2
    else:
        total_chars = sum(len(s) for s in lst1)
        return lst1[:total_chars] + lst2[total_chars:]
```

