def any_int(x, y, z):
    # Checking if all numbers are integers
    if not all(isinstance(num, int) for num in [x, y, z]):
        return False

    # Checking if any number is the sum of the other two
    if x + y == z or y + z == x or z + x == y:
        return True
    else:
        return False

