def encode(message):
    for letter in message.lower():
        if letter.isalpha():
            if letter in 'aeiou':
                i = ord(letter) - ord('a')
                letter = chr((i + 3) % 26 + ord('a'))
            else:
                letter = chr((ord(letter) - ord('a') + 2) % 26 + ord('a'))
    return ''.join(letter for letter in message if letter.isalpha()).lower()
