import string

def get_closest_vowel(word):
    """
    Find the closest vowel that stands between two consonants from the right side
    of the word (case sensitive).

    Vowels in the beginning and ending don't count. Return empty string if you didn't
    find any vowel met the above condition.
    """
    vowels = string.ascii_lowercase
    closest_vowel = ''

    for i in range(len(word)):
        if i == 0 and word[i] in vowels:
            if word[i+1] in vowels:
                closest_vowel = word[i]
        elif word[i-1] in vowels and word[i] in vowels:
            if word[i-1] != word[i] and word[i] in vowels:
                closest_vowel = word[i]
        elif word[i] in vowels:
            if word[i-1] in vowels and word[i] in vowels:
                if abs(ord(word[i-1]) - ord(word[i])) < abs(ord(word[i-1]) - ord(word[i])):
                    closest_vowel = word[i]
    return closest_vowel
```

