def is_nested(s):
    # Define the nested brackets
    nested_brackets = ['[', ']', '[]', '[][]', '[]']

    # Dictionary to map characters to their indices
    bracket_indices = {'(': 0, '[': 1, '{': 2, '<': 3}

    # Initialize the answer
    answer = False

    # Iterate through each character in the string
    for i, char in enumerate(s):
        # Check if the character is a bracket
        if char in nested_brackets:
            # If the character is a bracket, check the nested brackets
            if i + 1 < len(s) and bracket_indices[s[i + 1]] > bracket_indices[char]:
                answer = True
        # If the character is not a bracket, check for the nested brackets
        elif i < len(s) - 1 and bracket_indices[s[i]] == bracket_indices[char]:
            answer = True

    # Return True if a nested bracket was found or the string is valid
    return answer or not any(answer for _ in s)

```

