def is_nested(string):
    def is_nested_helper(substring, index):
        if index == len(string) or string[index] != '[':
            return False
        if substring.isalpha() and string[index] == substring[0]:
            return is_nested_helper(substring[1:], index + 1)
        if substring.isnumeric() and string[index] == substring[0]:
            return is_nested_helper(substring[1:], index + 1)
        return string[index] in ['[', ']', '{', '}', '<', '>', '|', '?', '@', '!', '\\', ',', '.', '/', '?', '*']

    return is_nested_helper(string, 0)
