```python
import math


def is_even(n):
    """ Check if a number is even. """
    return n % 2 == 0


def find_zero(xs: list):
    """ Find zero of a polynomial with even coefficients. """
    if len(xs) % 2 != 0:
        raise ValueError("Polynomial must have an even number of coefficients.")

    denom = 1
    # Avoid division by zero
    for i, coeff in enumerate(xs):
        if coeff == 0:
            return None
        denom *= i + 1
        if denom == 0:
            raise ZeroDivisionError("Expression is zero at zero or undefined denominator.")

    # Exact zero at x = 0
    if len(xs) == 0 or xs[0] == 0:
        return [xs[0]]

    # Handling last term
    last_coeffs_remaining = 0
    for i, coeff in enumerate(reversed(xs)):
        # Skip constant term coefficient
        if last_coeffs_remaining == 0:
            break
        if format(coeff, '.70f') + xs[i] * denom < 0:
            return None
        last_coeffs_remaining += coeff

    def f(x):
        return xs[0] + xs[1] * x + xs[2] * x**2

    return set(map(f, repeat(len(xs) // 2)))
