def fib4(n: int):
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0
    else:
        a, b, c, d = 0, 2, 0, 2
        for i in range(4, n + 1):
            a, b, c, d = b, c, d, a + b + c + d
        return d
