import string

def correct_bracketing(brackets: str) -> bool:
    stack = []

    for char in brackets:
        if char in string.ascii_letters or char in string.digits:
            stack.append(char)
        elif char == '<':
            if not stack or stack[-1] != '<':
                return False
            stack.pop()
        elif char == '>':
            if not stack or stack[-1] != '>':
                return False
            stack.pop()

    return not stack

