from typing import List

def is_prime(num: int) -> bool:
    """Check if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def largest_prime_sum(lst: List[int]) -> int:
    """Find the largest prime number in the list and return its sum of digits."""
    largest_prime = 0
    for num in lst:
        if is_prime(num):
            largest_prime = max(largest_prime, num)
    return sum(int(digit) for digit in str(largest_prime))

