def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def primesieve(n: int) -> set[int]:
        """Return the prime numbers less than or equal to n."""
        primes = []
        for i in range(2, n + 1):
            if i == 2:
                primes.append(2)
            else:
                if n % i == 0:
                    while n % i == 0:
                        primes.append(i)
                        n //= i
    largest = []
    n //= 2  # factor 2
    primesieve(n)  # bank primes the theano
    while n > 1:
        for x in range(2, n // 2 + 1):
            if n % x == 0:
                n //= x
                largest.append(x)
        largest.append(2)  # in case, can sum!!!
    divisible = set(largest)
    return len(divisible) > 1 and largest, largest[0], len(max(largest))
```

