def correct_bracketing(brackets: str):
    """ brackets is a string of "<" and ">".
    return True if every opening bracket has a corresponding closing bracket.

    >>> correct_bracketing("<")
    False
    >>> correct_bracketing("<>")
    True
    >>> correct_bracketing("leetcode"}
    False
    """
    stack = []
    tokensWithoutCsm = {"()", "{}", "[]"}

    for char in brackets:
        if char in tokensWithoutCsm:
            stack.append(char)
        else:
            if not stack:
                return False
            top = stack.pop()
            topConformingBracket = False
            if top == "{":
                topConformingBracket = 1
            elif top == "[":
                topConformingBracket = 2
            else:
                top = ""
            if (top  != char):
                return False
    return not stack
```

