import sys

def max_fill(grid, capacity):
    import math

    max_flow = 0
    while True:
        max_cap_per_bucket, changes = divmod(capacity, len(grid[0]))

        if changes == 0:
            max_flow = max_flow + changes
            break

        to_remove_water = len(grid[0]) - changes * max_cap_per_bucket
        capacity -= to_remove_water
        capacity = max(0, capacity)

        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == 0:
                    grid[r][c] = 1
                else:
                    if grid[r][c - to_remove_water] == 0:
                        grid[r][c - to_remove_water] = 0
                    else:
                        grid[r][c - to_remove_water] = 1
    return max_flow

