    def even_odd_count(num):
        # Define a lambda function to count the number of even and odd digits in an integer
        def count_even_odd(x):
            even_count = 0
            odd_count = 0
            while x > 0:
                digit = x % 10
                if digit % 2 == 0:
                    even_count += 1
                else:
                    odd_count += 1
                x //= 10
            return even_count, odd_count
        # Call the lambda function with the input number and return the results
