def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

class HexKeysCounter:
    def hex_key(self, num):
        """Count the number of hexadecimal digits that are prime."""
        prime_count = 0
        for char in num:
            if char == "0" or char == "1" or char == "2" or char == "3" or char == "4" or char == "5" or char == "6" or char == "7" or char == "8" or char == "9" or char == "A" or char == "B" or char == "C" or char == "D" or char == "E" or char == "F":
                prime_count += 1
            elif is_prime(char):
                prime_count += 1
        return prime_count

