import string

def encode(message):
    alphabet = string.ascii_lowercase
    encoded_message = ''

    for char in message:
        if char in alphabet:
            index = (alphabet.index(char) + 2) % len(alphabet)
            encoded_message += alphabet[index]
        else:
            encoded_message += char

