def histogram(test):
    '''Given a string containing space-separated lowercase letters, return a dictionary of the letter a with the 
    most occurrence and containing the corresponding count.

    Example:
    histogram('a b c') returns {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') returns {'a': 2, 'b': 2}
    histogram('a b c a b') returns {'a': 2, 'b': 2}
    histogram('b b b b a') returns {'b': 4}
    histogram(''). returns {}

    '''
    # First, find all non-numeric characters in the string
    possible_letters = [letter for letter in test if letter.isalpha()]
    # Then, count occurrences of each possible letter
    letter_count = {letter: test.count(letter) for letter in possible_letters}
    highest_count, highest_letters_with_count = max(letter_count.items(), key=lambda x: (-x[1], x[0]))
    # Return the returned letter, a and its count alongside its most occurrences letter and count
    return highest_letters_with_count, highest_count
