import math

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def count_hex_digits(num):
    hex_digits = '0123456789ABCDEF'
    count = 0
    for digit in num:
        if digit in hex_digits:
            count += 1
    return count

def hex_key(num):
    if not num:
        return 0
    return count_hex_digits(num) + sum(1 for digit in num if is_prime(int(digit)))

