    """Generate all prime factors of n."""
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def is_simple_power(x, n):
    """Count all prime numbers x can be a simple power of n."""
    factors = prime_factors(n)
    for factor in factors:
        if x % factor == 0:
            return True
    return False

