    if not lst:
        return (None, None)

    negative_integers = [num for num in lst if num < 0]
    positive_integers = [num for num in lst if num >= 0]

    if not negative_integers and not positive_integers:
        return (None, None)

    if len(negative_integers) > len(positive_integers):
        a = negative_integers[0]
        b = positive_integers[0] if len(negative_integers) == len(positive_integers) else None
    else:
        a = positive_integers[0]
        b = negative_integers[0] if len(negative_integers) == len(positive_integers) else None

    return (a, b)
