def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    # If n is 1, there is only one number that starts or ends with 1, which is 1 itself.
    if n == 1:
        return 1
    else:
        # For n-digit numbers, there are 9 choices for the first digit (1-9) and 10^(n-2) choices for the remaining digits.
        return 9 * (10 ** (n - 2))
```

