    if not date:
        return False

    # Check if the date string is in the correct format
    if not date[0].isdigit() or not date[1].isdigit():
        return False

    # Check if the month is valid
    if not (1 <= int(date[0]) <= 12):
        return False

    # Check if the day is valid
