def valid_date(date):
    try:
        # Split the date string into month, day, and year
        month, day, year = date.split('-')
        # Check if the date is valid based on the rules
        if int(month) > 12 or int(month) < 1 or int(day) > 31 or int(day) < 1 or int(year) > 9999:
            return False
        # Check if the month is valid (1-12)
        if int(month) not in [1, 3, 5, 7, 8, 10, 12]:
            return False
        # Check if the day is valid (1-31)
        if int(day) not in [1, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]:
            return False
        # Check if the year is valid (1900-2099)
        if int(year) < 1900 or int(year) > 2099:
            return False
        # The date is valid
        return True
    except ValueError:
        # If the date cannot be split into month, day, and year, the date is invalid
        return False
