    if len(date) == 0:
        return False

    # Check the number of days in each month
    if date[2] == '-' and int(date[:2]) in [4, 6, 9, 11]:
        return False

    if date[2] == '-' and int(date[:2]) in [1, 3, 5, 7, 8, 10, 12]:
