def tri(n):
    """Calculates the Tribonacci sequence using dynamic programming."""
    if n == 1:
        return [3]
    elif n == 2:
        return [1, 3]
    else:
        tribonacci = [1, 3]  # Initialize the sequence with the first two numbers
        for i in range(2, n):
            tribonacci.append(tribonacci[i-1] + tribonacci[i-2] + tribonacci[i+1])
        return tribonacci

# Example usage
