def get_closest_vowel(word):
    vowels = set(['a', 'e', 'i', 'o', 'u'])  # Contains all the vowels in English alphabet
    # Iterate over each character in the word while skipping the cases where the left boundary is not owned vowel
    for i in range(len(word) - 1):
        if word[i] in vowels:
            missing = vowels - set(word[i + 1:])
            if len(missing):
                return i + missing.pop()  # Return the minimal one of all vowels

