def is_nested(string):
    """
    Checks if there is at least one nested bracket in a given string containing brackets.
    Nested brackets are considered as sequences of two or more consecutive brackets.
    """
    open_brackets = [{i: None} for i in string.lstrip("[[]").replace("]]]]]][[[[[]", "value"]}
    close_brackets = {}

    def recurse(index):
        if index >= len(open_brackets) * 2:
            return True
