import re

def split_words(txt):
    # Check for whitespace
    if re.search(r'\s', txt):
        # Split on whitespace
        return txt.split()
    # Check for commas
    elif re.search(r',', txt):
        # Split on commas
        return txt.split(',')
    # Check for lowercase letters with odd order in the alphabet
    else:
        # Calculate the number of lowercase letters with odd order in the alphabet
        return len([char for char in txt if ord(char) - ord('a') % 2 == 1])
