def tri(n):
    if n == 1:
        return [3]
    elif n == 2:
        return [1, 3]
    else:
        tribonacci = [1, 3]
        for i in range(2, n):
            next_value = tribonacci[-1] + tribonacci[-2] + tribonacci[-3]
            tribonacci.append(next_value)
        return tribonacci
