from typing import List

def find_largest_prime_sum(lst: List[int]) -> int:
    """
    Finds the largest prime number in the given list and returns the sum of its digits.
    """
    largest_prime = -1
    for num in lst:
        if is_prime(num) and num > largest_prime:
            largest_prime = num
    return sum(int(digit) for digit in str(largest_prime))

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

