def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    closest_vowel = ""

    # Iterate through the word from right to left
    for i in range(len(word) - 1, 0, -1):
        # Iterate through the consonants from the right to left
        for j in range(i, 0, -1):
            if word[j] in vowels:
                # If the current consonant is a vowel that is closest to the right of the word
                # and if it is not the closest vowel yet, update the closest_vowel
                if word[j] in vowels and closest_vowel == "":
                    closest_vowel = word[j]
                elif word[j] in vowels and closest_vowel != "" and abs(closest_vowel.index(word[j]) - i) < abs(closest_vowel.index(vowels) - i):
                    closest_vowel = word[j]
                break

    return closest_vowel if closest_vowel != "" else ""

