def intersection(interval1, interval2):
    if interval1[1] <= interval2[0] or interval1[0] >= interval2[1]:
        return "NO"
    start, end = min(interval1), max(interval2)
    is_prime = True
    for num in range(start, end + 1):
        if num in interval1 and num in interval2:
            continue
        if not is_prime:
            break
        divisible_times = interval1.count(num)
        division_times = interval2.count(num)
        if divisible_times * division_times != 1:
            is_prime = False
            break
    if is_prime:
        return "YES"
    return "NO"

