def compare_one(*args):
    """
    Create a function that takes multiple integers, floats, or strings representing
    real numbers as arguments and returns the larger variable in its first position.
    Return None if the first value is equal to or smaller than the second.
    Note: If the arguments are the same, or the type of the first argument is string, 
    then return the larger value directly.
    """
    if len(args) <= 1 or args[0] != args[1]:
        if args[0] == args[1]:
            return None
        else:
            return args[0]
    else:
        return max(args)
