def split_words(txt):
    # Check for whitespace
    if ' ' in txt:
        return txt.split()
    # Check for commas
    elif ',' in txt:
        return txt.count(',')
    else:
        # Return the number of lower-case letters with odd order in the alphabet
        return sum(ord(char) - ord('a') for char in txt if char.islower() and ord(char) - ord('a') % 2 == 1)
