from typing import List

def add_elements(arr: List[int], k: int) -> int:
    """
    Given a non-empty array of integers arr and an integer k, return
    the sum of the elements with at most two digits from the first k elements of arr.

    Example:

            Input: arr = [111,21,3,4000,5,6,7,8,9], k = 4
            Output: 24 # sum of 21 + 3

    Constraints:
        1. 1 <= len(arr) <= 100
        2. 1 <= k <= len(arr) 
    """
    # Find the k most frequent elements and keep them in a set
    loc = {}
    for num in arr:
        if num in loc:
            loc[num] += 1
        else:
            loc[num] = 1
    frequency = {}
    for num in loc.keys():
        frequency[num] = loc[num]

    # If there's anything left in the frequency dic, filter elements with at most 2 digits
    if frequency and frequency:
        kept_values = [i for i in sorted(frequency.keys()) if not (int(i[0:2]) > 9 or int(i[-2:]))]
        # If there are no filtered values in the frequency dic, return 0
        if not kept_values:
            return 0

    result = 0
    for num in frequency.keys():
        if num in kept_values:
            result += num
    return result
