def exchange(lst1, lst2):
    def is_even(num):
        # Check if the number is even
        return num % 2 == 0

    # Check if any element in lst1 is odd
    has_odd = any(is_even(num) for num in lst1)

    # Check if lst1 is already a list of even numbers
    if not lst1 or not all(is_even(num) for num in lst1):
        return "NO"

    exchange_count = 0
    for num in lst1:
        if not is_even(num):
            # Check if any element in lst2 is odd
            has_odd = any(is_even(num) for num in lst2)

            # Perform the exchange if necessary
            if not has_odd:
                lst2.append(num)
                exchange_count += 1
                if exchange_count == len(lst1):
                    return "YES"
            else:
                lst1.remove(lst2.pop())

    if not has_odd:
        return "YES"
    else:
        return "NO"
