import string

def encode(message):
    """
    Write a function that takes a message, and encodes in such a way that it swaps case 
    of all letters, replaces all vowels in the message with the letter that appears 
    2 places ahead of that vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    # Define the encryption function that swaps case, replaces vowels with 2 symbols ahead
    def encryption(message):
        encrypted_message = ""
        for char in message:
            if char.upper() in string.ascii_uppercase:
                if char.islower():
                    encrypted_message += char.lower()
                else:
                    encrypted_message += char.swapcase()
            elif char == ' ':
                encrypted_message += char  # Preserve spaces
            elif char in string.ascii_lowercase:
                encrypted_message += chr((ord(char) - ord('a') + 2) % 26 + ord('a'))
            else:
                encrypted_message += '?'
        return encrypted_message

    return encryption(message)
```

