def Strongest_Extension(class_name, extensions):
    strongest_extension = ""
    for extension in extensions:
        # Calculate the strength of the extension
        strength = sum(1 for letter in extension if letter.isupper()) - sum(1 for letter in extension if letter.islower())
        # Assign the strongest extension to the result
        if strength > 0:
            if strength > len(strongest_extension):
                strongest_extension = extension
    return class_name + "." + strongest_extension
