def intersection(interval1, interval2):
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    if start >= end:
        return "NO"
    prime = True
    for i in range(2, int(end/start) + 1):
        if end % i == 0:
            prime = False
            break
    if prime:
        return "YES"
    else:
        return "NO"
