def closest_integer(value):
    if value == '0':
        return 0
    elif '.' in value:
        # Split the number into integer and fractional parts and round the fractional part
        integer_part, fractional_part = map(float, value.split('.'))
        # Determine if the integer part is negative or positive
        if integer_part < 0:
            return -round(fractional_part)
        return round(integer_part)
    else:
        # If the number is not a float, check if it is close to an integer
        # Use rounding to find the closest integer
        integer_part = int(value)
        if value == round(value):
            return integer_part
        else:
            return round(value)
