def tri(n):
    if n == 1:
        return [3]
    elif n == 2:
        return [3, 1, 2]
    else:
        sequence = [1, 3, 2]
        while len(sequence) < n:
            next_value = sequence[-1] + sequence[-2] + sequence[-3]
            sequence.append(next_value)
            if next_value == 3:
                sequence[-1] = 1
            elif next_value == 5:
                sequence[-2] = 3
            elif next_value > 3:
                sequence.append(next_value - 2)
        return sequence[:n + 1]
