def tri(n):
    """Generate the Tribonacci sequence up to the nth number."""
    if n == 1:
        return [3]
    elif n == 2:
        return [1, 3]
    else:
        tribonacci = [1, 3]
        for i in range(2, n):
            tribonacci.append(tribonacci[i-1] + tribonacci[i-2] + tribonacci[i+1])
        return tribonacci
