    elif n == 2:
        return [1, 3]
    else:
        fib_sequence = [1, 3]
        for i in range(2, n):
            if i % 2 == 0:
                fib_sequence.append(1 + i / 2)
            else:
                fib_sequence.append(fib_sequence[i-1] + fib_sequence[i-2] + fib_sequence[i+1])
        return fib_sequence
