import math

def sum_squares(lst):
    if not lst:
        return 0

    total = 0
    for index, value in enumerate(lst):
        # Check if index is a multiple of 3 or 4
        if index % 3 == 0 or index % 4 == 0:
            # Calculate square of the value, if index is a multiple of 3
            total += value ** 2
        else:
            # Calculate cube of the value, if index is not a multiple of 3 or 4
            total += math.pow(value, 3)

    return total
```

