def how_many_times(string: str, substring: str) -> int:
    count = 0
    i = 0
    while i < len(string):
        if string[i] == substring[0]:
            overlaps = 0
            j = 1
            while j < len(substring):
                if string[i + j] == substring[j]:
                    overlaps += 1
                    if overlaps == len(substring) - 1:
                        count += 1
                        break
                else:
                    j += 1
                i += overlaps
        i += 1
    return count
