import sys
def will_it_fly(q, w):
    # Check if q is a palindrome
    if q == list(reversed(q)):
        # Calculate the sum of elements in q and its balanced version
        even_half_sum = (len(q) // 2) * (q[0] + q[len(q) // 2])
        odd_half_sum = sum(q[::2]) + sum(q[1::2])

        # Check if the sum of balanced q is less than or equal to w
        if odd_half_sum <= w:
            return True
        else:
            return False
    else:
        return False
