def decimal_to_binary(decimal):
    # Base case checking
    if decimal == 0:
        return "0"
    elif decimal < 0:
        return "db" + decimal_to_binary(-decimal) + "db"
    else:
        return "db" + decimal_to_binary(decimal // 2) + "db"
