        # Convert the date string to a datetime object
        date_obj = datetime.strptime(date, '%m-%d-%Y')

        # Check if the date is valid
        if date_obj.month in [1, 3, 5, 7, 8, 10, 12] or date_obj.month == 2:
            if date_obj.day > 30:
                return False
        elif date_obj.month in [4, 6, 9, 11] or date_obj.month == 2:
