from typing import List


def parse_music(music_string: str) -> List[int]:
    notes = music_string.split()
    result = []
    current_beat = 0
    length = len(notes)

    for i, note in enumerate(notes):
        beat = 0
        for char in note:
            if char == "|":
                beat += 2
            elif char == ".":
                beat += 1
            current_beat += 1
            if length <= i:
                break
        result.append(beat)

    return result
```

