def digits(n):
    if n < 10: 
        return 0
    prod = 1
    odd_digit = [str(d) for d in str(n)]
    for d in odd_digit: 
        if d == '1' or d == '3' or d == '5' or d == '7' or d == '9':
            prod *= int(d)
    return prod
