from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    balance = 0
    for char in paren_string:
        if char == ' ':
            continue
        elif char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        else:
            if balance > 0:
                result.append(''.join(result[-2::-1]))
                result.pop()
            if balance == 0:
                result.append(char)
    return result
