import numpy as np

def exchange(lst1, lst2):
    # Check if the total number of even numbers is less than or equal to the total number of elements
    if np.sum(lst1) > np.sum(lst2):
        return "NO"
    else:
        # Check if all elements in lst1 are already even
        if all(num % 2 == 0 for num in lst1):
            return "YES"
```

