class my_class:
    def __init__(self, extensions):
        self._extensions = extensions

    def strongest_extension(self):
        strongest_extension = None
        strongest_strength = 0
        for extension in self._extensions:
            if strongest_extension is None or abs(ord(extension[0]) - ord(extension[0].lower())) > strongest_strength:
                strongest_extension = extension
                strongest_strength = abs(ord(extension[0]) - ord(extension[0].lower()))
        return strongest_extension + "." + str(strongest_strength)

# Example usage
extension_list = ['SErviNGSliCes', 'Cheese', 'StuFfed']
my_class_instance = my_class(extension_list)
print(my_class_instance.strongest_extension())  # Output: my_class.SErviNGSliCes
```

