from typing import List, Tuple

def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    # Sort the list and split it into two parts, i.e., the first half and the second half.
    sorted_numbers = sorted(numbers)
    length = len(sorted_numbers)
    mid = length // 2

    # Elif greater than mid, first half is the answer
    if length > mid:
        return tuple(sorted_numbers[:mid]), (sorted_numbers[mid])
    # Elif less than mid, second half is the answer
    else:
        return (sorted_numbers[mid]), tuple(sorted_numbers[len(sorted_numbers):length])
