def fibfib(n: int) -> int:
    if n == 0 or n == 1 or n == 2:
        return 0
    elif n == 3:
        return 1
    else:
        a, b, c = 0, 0, 1
        for _ in range(n - 3):
            a, b, c = b, c, a + b + c
        return c
