def search(lst):
    if not lst:
        return -1

    # Count the frequency of each element in the list
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Find the greatest integer that meets the criteria
    for num in lst:
        if freq[num] >= num and freq.get(num, 0) == 0:
            return num

    return -1
