def check_dict_case(dict):
    """
    Given a dictionary, return True if all keys are strings in lower 
    case or all keys are strings in upper case, else return False. The function should return False is the given dictionary is empty.
    """
    if len(dict) > 0:
        for char in dict.keys():
            if not char.isalpha():
                return False
    return all(char.isupper() or char.isspace() for char in dict.keys())
