def fizz_buzz(n: int):
    cache = {}
    for i in range(1, n):
        count = 0
        if i % 11 == 0:
            count += 1
        if i % 13 == 0:
            count += 1
        digits_str = str(i)
        if digits_str[0] == '1': count += 1

        if (digits_str[0], digits_str[1], digits_str[2], digits_str[3], digits_str[4], digits_str[5],
             digits_str[0] == '5' or digits_str[7] == '3') or (digits_str[0] == '7' or digits_str[4] in '39'):
            cache[i] = count
            if i % 7 == 0:
                return count   
    return cache[0] if cache and cache[0] > 0 else 0

# Examples
