def fizz_buzz(n: int) -> int:
    num_7s = 0

    for i in range(1, n):
        if i % 11 == 0 or i % 13 == 0:
            continue  # Skip numbers divisible by both 11 and 13

        parts = str(i)  # Get the number as a string
        for digit in parts:
            if digit == '7':
                num_7s += 1

    return num_7s
