import datetime

def valid_date(date):
    if not date:
        return False

    try:
        datetime.datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    for month in range(1, 13):
        if month in [3, 5, 8, 10] and (year := date.split('-')[2]) != f"{month:02d}-01-{year}" or month in [4, 6, 9, 11] and (year := date.split('-')[2]) != f"{month:02d}-04-{year}" or month == 2:
            return False

    return True
