from typing import List

def largest_smallest_integers(lst: List[int]) -> Tuple[List[int], List[int]]:
    negative_integers = [x for x in lst if x < 0]
    positive_integers = [x for x in lst if x > 0]
    if not negative_integers and not positive_integers:
        return (None, None)
    a = None if negative_integers else *[min(negative_integers)]
    b = None if positive_integers else *[max(positive_integers)]
    return (a, b)
```

