def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    # Split the test string into a list of characters
    characters = list(test)

    # Count the occurrences of each character
    character_counts = {}
    for char in characters:
        if char in character_counts:
            character_counts[char] += 1
        else:
            character_counts[char] = 1

    # Find the maximum occurrence and its corresponding characters
    max_occurrence = max(character_counts.values())
    most_common_characters = [char for char, count in character_counts.items() if count == max_occurrence]

    return most_common_characters

```

