import math

def bf(planet1, planet2):
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    distances = {
        'Mercury': 0.39,
        'Venus': 0.72,
        'Earth': 1,
        'Mars': 1.52,
        'Jupiter': 5.20,
        'Saturn': 10.22,
        'Uranus': 29.47
    }

    # Calculate the total distance between the planets
    total_distance = distances[planet1] + distances[planet2]       
    max_distance = max(t * math.sin(0) for t in distances.values())  # Initialize max_distance with the smallest distance

    if planet1 < planet2:
        return ()

    good_planets = [(planet1, max_distance)]
    while good_planets:
        planet1, max_distance = good_planets.pop(0)

        # Check if the current planet's orbit overlaps with the next one
        for planet2 in sorted(set(["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]).difference([planet1])):
            if planet1 <= planet2 < planet2:
                good_planets.append((planet2, max_distance - distances[planet2]))
            elif planet2 == planet1:
