def search(lst):
    # Count the frequency of each element in the list
    frequency = {}
    for num in lst:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Find the greatest element with a frequency greater than or equal to its value
    greatest_element = -1
    for num, count in frequency.items():
        if count >= num and count > greatest_element:
            greatest_element = count

    return greatest_element
