        token = expr[i]
        if token in operators:
            if operation and operation[token] == 0:
                if len(stack) and len(stack) == 1 and stack[-1] is not None:
                    expression.insert(stack.index(stack[-1]), operators[token])
                    stack.pop()
                else:
                    # First operand in the context
                    if stack:
                        expression.insert(0, operators[token])
                    stack = [token]
