from math import sqrt

def is_prime(num):
    """Returns True if the provided number is prime, False otherwise"""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_fib(num: int) -> int:
    """Returns the nth Fibonacci number that is also prime"""
    count = 0
    n = num
    while True:
        fib_number = 0
        if is_prime(n):
            fib_number = n
            count += 1
        n += 1
        if count == num:
            return fib_number
        count = 0
```

