from typing import List, Tuple


def rolling_max_rat(numbers: List[int]) -> List[int]:
    """ From a given list of integers, generate a list of rolling maximum element found until given moment
    in the sequence.
    >>> rolling_max_rat([1, 2, 3, 2, 3, 4, 2])
    [1, 2, 3, 3, 3, 4, 4]
    """
    roll_max = []
    for i, num in enumerate(sorted(numbers, reverse=True)):
        if i == 0:
            roll_max.append(num)
        else:
            if roll_max + num <= roll_max[i-1]:
                roll_max += num
            else:
                roll_max.append(roll_max[-1] + num)
    return roll_max
```

