def smallest_change(arr):
    # Count the frequency of each element in the array
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Calculate the number of changes needed
    changes_needed = 0
    for freq_num, freq_count in freq.items():
        if freq_count % 2 != 0:
            changes_needed += (freq_count // 2)

    return changes_needed
