from typing import Tuple
from collections import deque

def bf(planet1: str, planet2: str) -> Tuple[str, ...]:
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    distances = set()
    for planet in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        if planet != planet1 and planet != planet2:
            distances.add(planet)

    planets = deque()
    for planet in sorted(distances):
        planets.appendleft(planet)

    return tuple(planets)
