from typing import List

def sum_of_digits_of_largest_prime(lst: List[int]) -> int:
    from math import sqrt
    largest_prime = -1
    largest_prime_sum = 0
    for num in lst:
        if is_prime(num):
            current_sum = sum(int(digit) for digit in str(num))
            if current_sum > largest_prime_sum:
                largest_prime = num
                largest_prime_sum = current_sum
    return largest_prime_sum

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

