    if isinstance(value, float) and value > 0:
        # Find the closest integer by adding 0.5 to the value
        return int(value + 0.5)
    # Check if the value is a float and negative
    elif isinstance(value, float) and value < 0:
        # Find the closest integer by subtracting 0.5 from the value
        return int(value - 0.5)
    # If the value is not a number, return the original value
    else:
        return value
