def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Initialize a dictionary to store the frequency of each letter
    frequency = {}

    # Count the frequency of each letter in the input string
    for letter in test:
        if letter in frequency:
            frequency[letter] += 1
        else:
            frequency[letter] = 1

    # Find the letter with the highest frequency and its count
    max_count = 0
    most_repeated_letter = None
    for letter, count in frequency.items():
        if count > max_count:
            max_count = count
            most_repeated_letter = letter

    # Return the dictionary with the most repeated letter and its count
    return {'most_repeated': most_repeated_letter, 'count': max_count}
