import math


def poly(xs: list, x: float) -> float:
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list) -> float:
    """ Find zero of the polynomial """
    # Ensure xs have even number of coefficients and largest non-zero coefficient
    if sum(i == 0 for i in xs) == len(xs) // 2 and max(xs) != 0:
        return None
    # Calculate the roots using the Newton-Raphson method
    for _ in range(1000):
        root = xs[0] - poly(xs, xs[0]) / xs[0]
        if abs(root) < 1e-10:
            return root
    return None
