```python
def count_up_to(n):
    if n <= 1:
        return []
    elif n == 2:
        return [2]
    s = {2, 3}
    number = 5
    arr = [2, 3, 5]
    while len(arr) < n:
        if all(number % x for x in s):
            number += 2  # Check for offset leap year
        elif number % 6 != 1:
            number += 2
        else:
            number += 4
        s.add(number)  # Keep a track of numbers that were discovered
    return arr
```

