import math

def will_it_fly(q, w):
    # Calculate the sum of the first element of the balanced list
    sum_first_element = q[0]

    # Calculate the sum of the rest of the elements
    rest_sum = sum(q[1:])

    # Check if the sum of the rest of the elements is less than or equal to the maximum possible weight
    if rest_sum <= w:
        # Check if the first element of the list is equal to the last element
        if q[0] == q[-1]:
            # Check if the list is balanced
            if q[0] == q[-1] and sum_first_element == rest_sum:
                return True
            else:
                return False
        else:
            return will_it_fly(q[1:], w)
    else:
        return False
