def words_in_sentence(sentence):
    import collections
    def is_prime(n):
        if n == 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def shortest_word(word):
        words = sentence.split()
        for word in words:
            if len(word) == 1 and is_prime(len(word)):
                return word
        return None

    words = sentence.split()
    return " ".join(shortest_word(word) for word in words)
