from typing import Tuple

def even_odd_palindrome(n):
    if n < 5:
        even_set = [i for i in range(1, n+1) if i % 2 == 0]
        odd_set = [i for i in range(1, n+1) if i % 2 != 0]
        return len(even_set), len(odd_set)
    else:
        even_palindrome_sub = n // 2 - even_odd_palindrome(ceil(n/2))
        odd_palindrome_sub = n - odd_odd_palindrome(n)
        return even_palindrome_sub, odd_palindrome_sub
```

