def factorial(n):
    """Returns the factorial of a number."""
    if n <= 1:
        return 1
    else:
        return n * factorial(n-1)

def sum_of_numbers(n):
    """Returns the sum of numbers from 1 to n."""
    return sum(range(1, n+1))

def f(n):
    """Implements the function f such that it takes n as a parameter and returns a list of size n."""
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_of_numbers(i))
    return result

