def check_if_last_char_is_a_letter(txt):
    if len(txt) <= 1:
        return False

    # Check if the last character is alphabetical and not part of a word
    last_char = txt[-1].lower()
    for char in txt:
        if char.isalpha() and char not in txt[:-1]:
            if last_char == char:
                return False
            last_char = char
            break

    return True
