import math

def is_simple_power(x, n):
    """Check if x is a simple power of n"""
    if n == 1:
        return x == n
    for _ in range(2, int(math.log(x, n)) + 1):
        if x % n == 0:
            return False
    return x == n ** (len(str(x)) - 1)

