from typing import Tuple

def bf(planet1: str, planet2: str) -> Tuple[str, ...]:
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()
    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()
    if planet2 < planet1:
        return ()
    planets = [
        planet1,
        "Venus",
        "Earth",
        "Mars",
        "Jupiter",
        "Saturn",
        "Uranus",
    ]
    return tuple(sorted(planets, key=lambda x: x.lower()))
```

```python
def is_simple_power(x, n):
    if n <= 1:
        return False
    while n ** (x - 1) <= x:
        n -= 1
    return n == x
```
